// Isolated diagnostic hypothesis checks. Never edits a generator or an archived output.
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,mkdtempSync,cpSync} from 'node:fs';
import {resolve,dirname,relative} from 'node:path';
import {pathToFileURL} from 'node:url';
import {spawnSync} from 'node:child_process';
import {inspectGenerated,containedPath,repositoryRoot,sha256,loadCatalog,inputFor} from '../test/typescript/verification/catalog.mjs';
const root=repositoryRoot;
const evidence=JSON.parse(readFileSync(resolve(root,'test/typescript/verification/evidence/preimplementation-v43.json'),'utf8'));
const artifactPath=resolve(root,evidence.sourceReports.artifacts.path);
const raw=readFileSync(artifactPath);assert.equal(sha256(raw),evidence.sourceReports.artifacts.sha256);
const artifacts=JSON.parse(raw);
const runtimePath=resolve(root,artifacts.sourceReport);
const runtime=JSON.parse(readFileSync(runtimePath,'utf8'));
const parent=resolve(root,'.tmp/prerequisite-design-probes');mkdirSync(parent,{recursive:true});
const out=mkdtempSync(resolve(parent,'run-'));
const result={version:1,kind:'isolated-hypothesis-not-production-fix',productionChanged:false,baselineRevision:evidence.baselineRevision,binarySha256:evidence.binarySha256,node:process.version,sourceArtifactReport:relative(root,artifactPath),sourceArtifactReportSha256:sha256(raw),strict:[],webhooks:[],status:'running'};
const save=()=>writeFileSync(resolve(out,'report.json'),JSON.stringify(result,null,2)+'\n');
const tsc=resolve(root,'test/typescript/node_modules/typescript/lib/tsc.js');
try {
 for(const entry of artifacts.fixtures.filter(f=>f.status==='baseline-blocked')){
  const fixture=loadCatalog().local.find(f=>f.id===entry.id);assert.ok(fixture);
  const spec=JSON.parse(readFileSync(inputFor(fixture).path,'utf8'));
  const streamRoutes=[];
  for(const [path,item] of Object.entries(spec.paths??{}))for(const [method,operation] of Object.entries(item)){
   if(!operation || typeof operation!=='object' || !operation.responses)continue;
   const success=Object.entries(operation.responses).filter(([s])=>/^2/.test(s));
   if(success.length && success.every(([,r])=>Object.keys(r.content??{}).length>0 && Object.entries(r.content).every(([media,v])=>v?.itemSchema!==undefined || media==='text/event-stream')))streamRoutes.push(method.toUpperCase()+' '+path);
  }
  assert.ok(streamRoutes.length,'missing stream-only negative case '+entry.id);
  for(const variant of ['baseline','candidate']){
   const source=resolve(dirname(runtimePath),entry.id,variant,'source');const audit=inspectGenerated(source);
   assert.equal(audit.treeSha256,runtime.fixtures.find(f=>f.id===entry.id).generated[variant].treeSha256);
   const dest=resolve(out,entry.id,variant);mkdirSync(dest,{recursive:true});
   for(const file of Object.keys(audit.files))if(file.endsWith('.ts')){
    const to=containedPath(dest,file);mkdirSync(dirname(to),{recursive:true});writeFileSync(to,readFileSync(containedPath(source,file),'utf8').replaceAll('// @ts-nocheck\n',''));
   }
   writeFileSync(resolve(dest,'package.json'),'{"type":"module","private":true}\n');
   const oldConfig=JSON.parse(readFileSync(entry.variants[variant].strictConfig,'utf8'));
   const config={compilerOptions:{...oldConfig.compilerOptions,noEmit:true},include:['**/*.ts']};
   delete config.compilerOptions.outDir;writeFileSync(resolve(dest,'tsconfig.json'),JSON.stringify(config,null,2));
   const callables=resolve(dest,'internal/runtime/callables.ts');let text=readFileSync(callables,'utf8');
   const old='Call extends (...args: never[]) => unknown';assert.equal(text.split(old).length-1,1);
   const beforeHash=sha256(text);text=text.replace(old,'Call extends object');writeFileSync(callables,text);
   const probe=['import type {Routes} from "./index.js";','import {assignCallableProperties} from "./internal/runtime/callables.js";'];
   streamRoutes.forEach((route,i)=>probe.push(`declare const stream${i}: Routes[${JSON.stringify(route)}]["call"];`,`// @ts-expect-error A stream-only public operation must remain non-callable.`,`stream${i}();`));
   probe.push('// @ts-expect-error Primitive targets must remain rejected.','assignCallableProperties(1, {});','const callback = (value: string): string => value;','const augmented = assignCallableProperties(callback, {id: 1});','const output: string = augmented("x");','void output;');
   writeFileSync(resolve(dest,'prerequisite.consumer.ts'),probe.join('\n')+'\n');
   const p=spawnSync(process.execPath,[tsc,'--project',resolve(dest,'tsconfig.json')],{cwd:root,encoding:'utf8',timeout:180000,maxBuffer:8*1024*1024});
   writeFileSync(resolve(dest,'strict.log'),(p.stdout??'')+(p.stderr??''));if(p.error)throw p.error;
   assert.equal(p.status,0,entry.id+'/'+variant+' '+p.stdout+' '+p.stderr);
   result.strict.push({fixture:entry.id,variant,status:'pass',patch:'single generic constraint widened to object; no runtime or exported Call changes',beforeHash,afterHash:sha256(text),streamOnlyNegativeRoutes:streamRoutes,strictFlags:config.compilerOptions,log:relative(root,resolve(dest,'strict.log'))});save();
  }
 }
 // Reuse the existing collision fixture, with its actual nonbundled ESM output.
 for(const variant of ['baseline','candidate']){
  const src=resolve(dirname(runtimePath),'collisions',variant,'esm');
  const {createWebhookRouter:before}=await import(pathToFileURL(resolve(src,'server/webhooks.js')));
  await assert.rejects(before({}, {routes:{}}).fetch(new Request('https://host.test/unmatched')),/startsWith/);
  const dest=resolve(out,'webhook-'+variant);cpSync(src,dest,{recursive:true});
  const file=resolve(dest,'server/webhooks.js');let text=readFileSync(file,'utf8');
  const spec=JSON.parse(readFileSync(resolve(root,'test/typescript/fixtures/collisions.openapi.json'),'utf8'));
  let replacements=0;
  // Controlled generated-code hypothesis, not a production text-rewrite algorithm.
  text=text.replace(/routes\[("(?:[^"\\]|\\.)*")\]/g,(match,key)=>{assert.ok(Object.hasOwn(spec.webhooks,JSON.parse(key)));replacements++;return `(Object.hasOwn(routes, ${key}) ? routes[${key}] : undefined)`;});
  assert.ok(replacements>0);writeFileSync(file,text);
  const {createWebhookRouter:after}=await import(pathToFileURL(file));
  assert.equal((await after({}, {routes:{}}).fetch(new Request('https://host.test/unmatched'))).status,404);
  let seen=0;
  const keys=Object.keys(spec.webhooks);
  const routes=Object.fromEntries(keys.map((name,i)=>[name,'/hook/'+i]));
  const handlers=Object.fromEntries(keys.map(name=>[name,{POST:async()=>{seen++;return {status:204};}}]));
  const router=after(handlers,{routes,authenticate:async()=>undefined});
  for(let i=0;i<keys.length;i++)assert.equal((await router.fetch(new Request('https://host.test/hook/'+i,{method:'POST'}))).status,204);
  assert.equal(seen,keys.length);
  let getterReads=0;const proto={};Object.defineProperty(proto,'__proto__',{get(){getterReads++;throw Error('inherited route getter must not execute');}});
  assert.equal((await after({}, {routes:Object.create(proto)}).fetch(new Request('https://host.test/unmatched'))).status,404);assert.equal(getterReads,0);
  result.webhooks.push({variant,status:'pass',baselineErrorReproduced:true,patch:'own-route lookup only in isolated generated ESM',emptyOrdinaryMapStatus:404,registeredOwnKeys:keys,registeredStatus:204,inheritedGetterReads:getterReads,replacements});save();
 }
 result.status='pass';
} catch(error){result.status='failed';result.error={message:error.message,stack:error.stack};process.exitCode=1;}finally{save();}
console.log(JSON.stringify({status:result.status,strictChecks:result.strict.length,webhookChecks:result.webhooks.length,report:relative(root,resolve(out,'report.json')),error:result.error?.message},null,2));
